            this.paddle2Y = J.JMath.max(0, J.JMath.min(this.paddle2Y, ((GameContext.BOARD_HEIGHT - GameContext.PADDLE_HEIGHT) | 0)));
            AIContext.aiPaddleY = J.JMath.max(0, J.JMath.min(AIContext.aiPaddleY, ((GameContext.BOARD_HEIGHT - GameContext.PADDLE_HEIGHT) | 0)));
            // Update ball position to stay within bounds with smooth transition
            this.ballX = J.JMath.max(0, J.JMath.min(this.ballX, ((GameContext.BOARD_WIDTH - GameContext.BALL_SIZE) | 0)));
            this.ballY = J.JMath.max(0, J.JMath.min(this.ballY, ((GameContext.BOARD_HEIGHT - GameContext.BALL_SIZE) | 0)));
            // Update demo ball and paddle positions to stay within bounds
            this.demoBallX = J.JMath.max(0, J.JMath.min(this.demoBallX, ((GameContext.BOARD_WIDTH - GameContext.BALL_SIZE) | 0)));
            this.demoBallY = J.JMath.max(0, J.JMath.min(this.demoBallY, ((GameContext.BOARD_HEIGHT - GameContext.BALL_SIZE) | 0)));
            this.demoPaddleY = J.JMath.max(0, J.JMath.min(this.demoPaddleY, ((GameContext.BOARD_HEIGHT - GameContext.PADDLE_HEIGHT) | 0)));
            this.demoRedPaddleY = J.JMath.max(0, J.JMath.min(this.demoRedPaddleY, ((GameContext.BOARD_HEIGHT - GameContext.PADDLE_HEIGHT) | 0)));
            GameContext.previewPaddleY = J.JMath.max(0, J.JMath.min(GameContext.previewPaddleY, ((GameContext.BOARD_HEIGHT - GameContext.PADDLE_HEIGHT) | 0)));
            // Increased base size
