                g.setColor(hoverColor);
                g.fillRect(0, 0, GameContext.BOARD_WIDTH, GameContext.BOARD_HEIGHT);
                // Add a pulsing border effect
                let borderSize = 4.0;
                // Pulsing effect
                let alpha = Math.fround(((0.5 + (0.3 * J.JMath.sin((J.$currentTimeMillis() * 0.005))))));
                let borderColor = new J.Color(100, 150, 255, J.$i((Math.fround(alpha * 100))));
                g.setColor(borderColor);
                // Draw border
                let borderStroke = new J.BasicStroke(borderSize);
