            g.setColor(J.Color.WHITE);
            let titleSize = Math.fround(((36 * J.JMath.min(this.scaleX, this.scaleY))));
            g.setFont(FontContext.primaryFont.deriveFont(titleSize));
            let titleFm = g.getFontMetrics();
