            this.drawSettingColumn(g, originalTransform);
            // Dynamic instructions based on current column position
            g.setColor(new J.Color(120, 120, 120));
            let instructionSize = Math.fround(((14 * J.JMath.min(this.scaleX, this.scaleY))));
            g.setFont(FontContext.secondaryFont.deriveFont(instructionSize));
            let instructions;
            if (SettingsContext.inCategoryColumn) {
                instructions = PongGame.getText("UI_ESC_BACKSPACE_HOME");
            } else {
                instructions = PongGame.getText("UI_ESC_BACKSPACE_BACK");
            }
            let fm = g.getFontMetrics();
            // Proprio nell'angolo sinistra
            let instructionX = J.$i(((10 * this.scaleX)));
            // Proprio in basso
