            let rightColor1, rightColor2, rightGlowColor;
            if ((AnimationContext.paddleTranslationProgress < 0.5)) {
                // First half: original red colors
                rightColor1 = new J.Color(255, 100, 100);
                rightColor2 = new J.Color(255, 150, 150);
                // Theme-based glow
                rightGlowColor = this.generalSettings.getPaddleGlowColor(false);
            } else {
                // Second half: transition to black
                let blackProgress = (((AnimationContext.paddleTranslationProgress - 0.5)) * 2.0);
                rightColor1 = this.interpolateToBlack(new J.Color(255, 100, 100), blackProgress);
                rightColor2 = this.interpolateToBlack(new J.Color(255, 150, 150), blackProgress);
                rightGlowColor = this.interpolateToBlack(this.generalSettings.getPaddleGlowColor(false), blackProgress);
            }
            // Draw right paddle glow
