        calculateBackgroundSpeedFromSetting() {
            // Default speed
            let speed = 2.0;
            // Check current selected category and its settings
            if (((SettingsContext.selectedCategory >= 0) && (SettingsContext.selectedCategory < SettingsContext.categorySettings.length))) {
                let currentSettings = SettingsContext.categorySettings[SettingsContext.selectedCategory];
                for (let i = 0; (i < currentSettings.length); (i++)) {
                    let settingId = currentSettings[i];
                    let currentValue = this.getCurrentCategorySettingValue(SettingsContext.selectedCategory, i);
                    // Apply speed multiplier based on setting values
                    if (("SETTING_AI_DIFFICULTY" === settingId)) {
                        switch (currentValue) {
                            case "FACILE":
                                // Very slow
                                speed = (speed * 0.3);
                                break;
                            case "NORMALE":
                                // Moderate
                                speed = (speed * 0.6);
                                break;
                            case "DIFFICILE":
                                // Normal
                                speed = (speed * 1.0);
                                break;
                            case "ESPERTO":
                                // Fast
                                speed = (speed * 1.8);
                                break;
                            case "IMPOSSIBILE":
                                // Very fast
                                speed = (speed * 3.5);
                                break;
                        }
                    } else if (("SETTING_PADDLE_SPEED" === settingId)) {
                        switch (currentValue) {
                            case "FACILE":
                                speed = (speed * 0.4);
                                break;
                            case "NORMALE":
                                speed = (speed * 0.7);
                                break;
                            case "DIFFICILE":
                                speed = (speed * 1.0);
                                break;
                            case "ESPERTO":
                                speed = (speed * 1.6);
                                break;
                            case "IMPOSSIBILE":
                                speed = (speed * 3.0);
                                break;
                        }
                    } else if (("SETTING_BALL_SPEED" === settingId)) {
                        // Ballspeed is numeric, convert to multiplier
                        try {
                            let ballSpeed = J.Integer.parseInt(currentValue);
                            if ((ballSpeed <= 2)) {
                                speed = (speed * 0.3);
                            } else if ((ballSpeed <= 4)) {
                                speed = (speed * 0.6);
                            } else if ((ballSpeed <= 6)) {
                                speed = (speed * 1.0);
                            } else if ((ballSpeed <= 8)) {
                                speed = (speed * 1.5);
                            } else {
                                speed = (speed * 2.5);
                            }
                        } catch ($e) {
                            if (J.$isException($e, 'NumberFormatException')) {
                                let e = J.$wrapException($e);
                            } else {
                                throw $e;
                            }
                        }
                    }
                }
            }
            // Clamp between 0.1 and 8.0
            return J.JMath.max(0.1, J.JMath.min(8.0, speed));
        }
