            let shakeX = J.$i(((x + shake)));
            let shakeY = J.$i(((y + (J.JMath.cos((AnimationContext.difficultyAnimationTime * 12)) * 3))));
            // Effetto fiamme - gradiente rosso-arancione-giallo che cambia
            let phase1 = ((J.JMath.sin((AnimationContext.difficultyAnimationTime * 4)) * 0.5) + 0.5);
            let phase2 = ((J.JMath.cos((AnimationContext.difficultyAnimationTime * 5)) * 0.5) + 0.5);
            let red = 255;
