                let flameOffset = J.$i(((J.JMath.sin(flamePhase) * 2)));
                let flameColor = new J.Color(red, J.JMath.max(0, ((green - Math.imul(i, 20)) | 0)), J.JMath.max(0, ((yellow - Math.imul(i, 50)) | 0)));
                g.setColor(flameColor);
