        pauseGame() {
            if (((AnimationContext.currentState === GameState.PLAYING) || (AnimationContext.currentState === GameState.SINGLE_PLAYER))) {
                this.wasSinglePlayer = ((AnimationContext.currentState === GameState.SINGLE_PLAYER));
                this.isPaused = true;
                // Save current ball velocity and set it to zero
                this.pausedBallVX = this.ballVX;
                this.pausedBallVY = this.ballVY;
                this.ballVX = 0;
                this.ballVY = 0;
                // Start transition animation
                this.startPauseTransition();
                J.System.out.println(("DEBUG: Gioco fermato e messo in pausa con transizione. Era single player: " + (this.wasSinglePlayer)));
            }
        }
        startPauseTransition() {
            this.isTransitioningToPause = true;
            this.pauseTransitionProgress = 0.0;
            this.centerLineRotation = 0.0;
            this.scoreTranslationProgress = 0.0;
            this.setState(GameState.TRANSITIONING);
        }
        updatePauseTransition() {
            if (!this.isTransitioningToPause) {
                return;
            }
            // Update transition progress
            this.pauseTransitionProgress = (this.pauseTransitionProgress + PongGame.PAUSE_TRANSITION_SPEED);
            // Smooth easing function (ease-in-out)
            let easedProgress = this.smoothStep(this.pauseTransitionProgress);
            // Update center line rotation (0 to π/4 radians)
            this.centerLineRotation = ((easedProgress * J.Math.PI) / 4);
            // Update score translation progress
            this.scoreTranslationProgress = easedProgress;
            // Check if transition is complete
            if ((this.pauseTransitionProgress >= 1.0)) {
                this.pauseTransitionProgress = 1.0;
                this.centerLineRotation = (J.Math.PI / 4);
                this.scoreTranslationProgress = 1.0;
                this.isTransitioningToPause = false;
                this.setState(GameState.PAUSED);
            }
        }
        smoothStep(t) {
            // Smooth step function for easing
            t = J.JMath.max(0.0, J.JMath.min(1.0, t));
            return ((t * t) * ((3.0 - (2.0 * t))));
        }
        unpauseGame() {
            if (this.isPaused) {
                // Start reverse transition instead of immediately resuming
                this.startResumeTransition();
                J.System.out.println(("DEBUG: Avvio transizione di ripresa gioco. Era single player: " + (this.wasSinglePlayer)));
            }
        }
        startResumeTransition() {
            this.isTransitioningFromPause = true;
            this.isTransitioningToPause = false;
            // Start from pause state (1.0)
            this.pauseTransitionProgress = 1.0;
            // Start from diagonal
            this.centerLineRotation = (J.Math.PI / 4);
            // Start from pause positions
            this.scoreTranslationProgress = 1.0;
            this.setState(GameState.TRANSITIONING);
            // Reset pause animation and message system
            this.pauseTimer = 0;
            this.showMotivationalMessage = false;
            this.messageScrollOffset = 0;
        }
        updateResumeTransition() {
            if (!this.isTransitioningFromPause) {
                return;
            }
            // Update transition progress (going backwards)
            this.pauseTransitionProgress = (this.pauseTransitionProgress - PongGame.PAUSE_TRANSITION_SPEED);
            // Smooth easing function (ease-in-out)
            let easedProgress = this.smoothStep((1.0 - this.pauseTransitionProgress));
            // Update center line rotation (π/4 to 0)
            this.centerLineRotation = (((J.Math.PI / 4)) * ((1.0 - easedProgress)));
            // Update score translation progress (1.0 to 0.0)
            this.scoreTranslationProgress = (1.0 - easedProgress);
            // Check if transition is complete
            if ((this.pauseTransitionProgress <= 0.0)) {
                // Complete the resume
                this.pauseTransitionProgress = 0.0;
                this.centerLineRotation = 0.0;
                this.scoreTranslationProgress = 0.0;
                this.isTransitioningFromPause = false;
                this.isPaused = false;
                // Restore ball velocity to resume game movement
                this.ballVX = this.pausedBallVX;
                this.ballVY = this.pausedBallVY;
                if (this.wasSinglePlayer) {
                    this.setState(GameState.SINGLE_PLAYER);
                    J.System.out.println("DEBUG: Ripreso gioco SINGLE_PLAYER dopo transizione");
                } else {
                    this.setState(GameState.PLAYING);
                    J.System.out.println("DEBUG: Ripreso gioco PLAYING dopo transizione");
                }
            }
        }
