            let actualGridWidth = ((Math.imul(AnimationContext.PADDLE_COLS, cardSize) + Math.imul((((AnimationContext.PADDLE_COLS - 1) | 0)), horizontalSpacing)) | 0);
            if ((actualGridWidth < availableWidth)) {
                // Distribuisci tutto lo spazio extra sui paddle (rendendoli più grandi)
                let extraSpace = ((availableWidth - actualGridWidth) | 0);
                cardSize = (cardSize + J.$idiv(extraSpace, AnimationContext.PADDLE_COLS)) | 0;
            }
            let totalGridWidth = ((Math.imul(AnimationContext.PADDLE_COLS, cardSize) + Math.imul((((AnimationContext.PADDLE_COLS - 1) | 0)), horizontalSpacing)) | 0);
            // Nessun margine - inizia dal bordo del pannello
            let gridStartX = panelX;
