        // Helper method to calculate realistic fire colors based on temperature/distance
        calculateFireColor(temperature, intensity, flicker) {
            // Simulate blackbody radiation colors (realistic fire physics)
            let alpha = Math.fround(Math.fround(intensity * flicker) * 255);
            if ((temperature > Math.fround(0.8))) {
                // Hottest: White-blue
                return new J.Color(255, 255, J.$i((Math.fround(200 + Math.fround(55 * temperature)))), J.$i(alpha));
            } else if ((temperature > Math.fround(0.6))) {
                // Hot: White-yellow
                return new J.Color(255, J.$i((Math.fround(255 * temperature))), J.$i((Math.fround(100 * temperature))), J.$i(alpha));
            } else if ((temperature > Math.fround(0.4))) {
                // Medium: Yellow-orange
                return new J.Color(255, J.$i((Math.fround(200 * temperature))), J.$i((Math.fround(50 * temperature))), J.$i(alpha));
            } else if ((temperature > Math.fround(0.2))) {
                // Cool: Orange-red
                return new J.Color(255, J.$i((Math.fround(150 * temperature))), 0, J.$i((Math.fround(alpha * Math.fround(0.8)))));
            } else {
                // Coolest: Dark red (cooling embers)
                return new J.Color(J.$i((Math.fround(Math.fround(255 * temperature) * temperature))), J.$i((Math.fround(100 * temperature))), 0, J.$i((Math.fround(alpha * Math.fround(0.6)))));
            }
        }
        // Intro slot machine animation
        drawIntro(g) {
            // Draw black background
            g.setColor(J.Color.BLACK);
            g.fillRect(0, 0, this.getWidth(), this.getHeight());
            // Get current time for animation
            let currentTime = J.$currentTimeMillis();
            let elapsedTime = (currentTime - this.introStartTime);
            // Phase 1: Show only "created by" text first (fade in)
            if ((elapsedTime < PongGame.INTRO_CREATED_BY_DURATION)) {
                // Calculate fade in alpha
                let alpha = 1.0;
                if ((elapsedTime < 400)) {
                    // Fade in during first 400ms
                    alpha = Math.fround(elapsedTime / 400.0);
                }
                alpha = J.JMath.max(0.0, J.JMath.min(1.0, alpha));
                // Draw "created by" text
                let createdBySize = Math.fround(((J.JMath.min(this.getWidth(), this.getHeight()) * 0.06)));
                let createdByFont = FontContext.secondaryFont.deriveFont(J.Font.PLAIN, createdBySize);
                g.setFont(createdByFont);
                g.setColor(new J.Color(200, 200, 200, J.$i((Math.fround(alpha * 255)))));
                let createdByText = "created by";
                let createdByFm = g.getFontMetrics();
                let createdByWidth = createdByFm.stringWidth(createdByText);
                let createdByX = J.$idiv((((this.getWidth() - createdByWidth) | 0)), 2);
                let createdByY = ((J.$idiv(this.getHeight(), 2) - J.$i(((this.getHeight() * 0.15)))) | 0);
                g.drawString(createdByText, createdByX, createdByY);
                // Don't show letters yet
                return;
            }
            // Draw "created by" text (now always visible)
            let createdBySize = Math.fround(((J.JMath.min(this.getWidth(), this.getHeight()) * 0.06)));
            let createdByFont = FontContext.secondaryFont.deriveFont(J.Font.PLAIN, createdBySize);
            g.setFont(createdByFont);
            g.setColor(new J.Color(200, 200, 200));
            let createdByText = "created by";
            let createdByFm = g.getFontMetrics();
            let createdByWidth = createdByFm.stringWidth(createdByText);
            let createdByX = J.$idiv((((this.getWidth() - createdByWidth) | 0)), 2);
            let createdByY = ((J.$idiv(this.getHeight(), 2) - J.$i(((this.getHeight() * 0.15)))) | 0);
            g.drawString(createdByText, createdByX, createdByY);
            // Initialize slot machine timing when transitioning to phase 2
            if (!this.introSlotMachineStarted) {
                this.introSlotMachineStarted = true;
                let slotMachineStartTime = currentTime;
                // Calculate when each letter should settle (staggered timing)
                for (let i = 0; (i < 4); (i++)) {
                    this.introLetterSettleTime[i] = (slotMachineStartTime + ((i * PongGame.LETTER_SETTLE_INTERVAL)));
                }
            }
            // Calculate time relative to slot machine start
            let slotMachineTime = (elapsedTime - PongGame.INTRO_CREATED_BY_DURATION);
            // 20% of screen size
            let letterSize = Math.fround(((J.JMath.min(this.getWidth(), this.getHeight()) * 0.2)));
            let letterFont = FontContext.primaryFont.deriveFont(J.Font.BOLD, letterSize);
            g.setFont(letterFont);
            // Calculate total width needed for 4 letters with spacing
            let fm = g.getFontMetrics(letterFont);
            // Approximate width
            let letterWidth = fm.charWidth("A");
            // Space between letters
            let spacing = J.$i(((letterWidth * 0.5)));
            let totalWidth = (((Math.imul(letterWidth, 4)) + (Math.imul(spacing, 3))) | 0);
            let startX = J.$idiv((((this.getWidth() - totalWidth) | 0)), 2);
            let centerY = ((J.$idiv(this.getHeight(), 2) + J.$idiv(fm.getAscent(), 2)) | 0);
            // Draw each letter
            for (let i = 0; (i < 4); (i++)) {
                let letterX = ((startX + (Math.imul(i, (((letterWidth + spacing) | 0))))) | 0);
                // Check if this letter should have settled yet
                if ((currentTime >= this.introLetterSettleTime[i])) {
                    if (!this.introLetterSettled[i]) {
                        // Letter just settled
                        this.introLetterSettled[i] = true;
                        this.currentIntroLetters[i] = PongGame.TARGET_LETTERS[i];
                    }
                    // Draw settled letter with white color
                    g.setColor(J.Color.WHITE);
                    g.drawString(("" + this.currentIntroLetters[i]), letterX, centerY);
                } else {
                    // Change letter every few frames for spinning effect
                    if ((J.$imod(slotMachineTime, 50) < 25)) {
                        // Change every 50ms
                        this.currentIntroLetters[i] = PongGame.RANDOM_LETTERS.charAt(this.introRandom.nextInt(PongGame.RANDOM_LETTERS.length));
                    }
                    // Draw spinning letter with dimmed color to show it's still changing
                    g.setColor(new J.Color(150, 150, 150));
                    g.drawString(("" + this.currentIntroLetters[i]), letterX, centerY);
                }
            }
            // Check if all letters have settled
            if ((!this.introComplete && this.allLettersSettled())) {
                this.introComplete = true;
            }
            // Draw transition fade overlay
            if ((this.isTransitioningFromIntro && (this.introTransitionProgress > 0))) {
                let fadeAlpha = J.$i(((this.introTransitionProgress * 255)));
                g.setColor(new J.Color(0, 0, 0, fadeAlpha));
                g.fillRect(0, 0, this.getWidth(), this.getHeight());
            }
        }
        allLettersSettled() {
            for (let settled of this.introLetterSettled) {
                if (!settled) {
                    return false;
                }
            }
            return true;
        }
        // First Access page methods
