        calculateFontSizeForWidth(g, text, targetWidth, baseFont) {
            // Inizia grande
            let fontSize = 200;
            let testFont = baseFont.deriveFont(J.Font.BOLD, fontSize);
            let fm = g.getFontMetrics(testFont);
            // Riduci la dimensione fino a che non rientra nella larghezza target
            while (((fm.stringWidth(text) > targetWidth) && (fontSize > 10))) {
                fontSize = Math.fround(fontSize - 5);
                testFont = baseFont.deriveFont(J.Font.BOLD, fontSize);
                fm = g.getFontMetrics(testFont);
            }
            return fontSize;
        }
