        startGameWithMode(gameMode) {
            SettingsContext.currentGameMode = gameMode;
            // Show selection briefly before starting game
            J.System.out.println(("Starting game with mode: " + SettingsContext.gameModes[gameMode]));
            // Handle different game modes
            switch (gameMode) {
                case 0:
                    // Go to main menu (home) where user can choose Single/Two Players
                    this.setState(GameState.MENU);
                    break;
                case 1:
                    // Go to Circle Mode menu first
                    this.setState(GameState.CIRCLE_MODE_MENU);
                    break;
                default:
                    this.setState(GameState.MENU);
                    break;
            }
        }
        // History input handler
        handleHistoryInput(e) {
            let filteredHistory = this.getFilteredHistory();
            switch (e.getKeyCode()) {
                case J.KeyEvent.VK_LEFT:
                    // Change mode selection
                    HistoryContext.selectedHistoryMode = J.JMath.max(0, ((HistoryContext.selectedHistoryMode - 1) | 0));
                    // Reset card selection when changing mode
                    HistoryContext.selectedHistoryCard = 0;
                    // Reset scroll when changing mode
                    HistoryContext.historyScrollOffset = 0;
                    break;
                case J.KeyEvent.VK_RIGHT:
                    // Change mode selection
                    HistoryContext.selectedHistoryMode = J.JMath.min(1, ((HistoryContext.selectedHistoryMode + 1) | 0));
                    // Reset card selection when changing mode
                    HistoryContext.selectedHistoryCard = 0;
                    // Reset scroll when changing mode
                    HistoryContext.historyScrollOffset = 0;
                    break;
                case J.KeyEvent.VK_UP:
                    // Navigate up through cards con scroll automatico
                    if (!filteredHistory.isEmpty()) {
                        if ((HistoryContext.selectedHistoryCard > 0)) {
                            (HistoryContext.selectedHistoryCard--);
                            // Scroll up se necessario
                            if ((HistoryContext.selectedHistoryCard < HistoryContext.historyScrollOffset)) {
                                HistoryContext.historyScrollOffset = HistoryContext.selectedHistoryCard;
                            }
                        }
                    }
                    break;
                case J.KeyEvent.VK_DOWN:
                    // Navigate down through cards con scroll automatico
                    if (!filteredHistory.isEmpty()) {
                        if ((HistoryContext.selectedHistoryCard < ((filteredHistory.size() - 1) | 0))) {
                            (HistoryContext.selectedHistoryCard++);
                            // Auto scroll down se la card selezionata non è più visibile
                            let maxVisible = this.calculateMaxVisibleCards();
                            if ((HistoryContext.selectedHistoryCard >= ((HistoryContext.historyScrollOffset + maxVisible) | 0))) {
                                HistoryContext.historyScrollOffset = ((((HistoryContext.selectedHistoryCard - maxVisible) | 0) + 1) | 0);
                            }
                        }
                    }
                    break;
                case J.KeyEvent.VK_ENTER:
                    // Action on selected card (placeholder for future functionality)
                    if ((!filteredHistory.isEmpty() && (HistoryContext.selectedHistoryCard < filteredHistory.size()))) {
                        let selectedEntry = filteredHistory.get(HistoryContext.selectedHistoryCard);
                        // TODO: Add card details view or other functionality
                        J.System.out.println(((("Selected card: " + selectedEntry.winner) + " vs ") + selectedEntry.gameMode));
                    }
                    break;
                case J.KeyEvent.VK_ESCAPE:
                case J.KeyEvent.VK_BACK_SPACE:
                    this.setState(GameState.MENU);
                    break;
            }
            this.repaint();
        }
        // Helper method per calcolare quante card sono visibili
        calculateMaxVisibleCards() {
            let cardHeight = J.$i(((110 * this.scaleY)));
            let cardSpacing = J.$i(((8 * this.scaleY)));
            let startY = J.$i(((170 * this.scaleY)));
            let availableHeight = ((((this.getHeight() - startY) | 0) - 50) | 0);
            return J.$idiv(availableHeight, (((cardHeight + cardSpacing) | 0)));
        }
        getFilteredHistory() {
            let filtered = new J.ArrayList();
            for (let entry of HistoryContext.gameHistory) {
                if (((HistoryContext.selectedHistoryMode === 0) && (entry.gameMode === "Single Player"))) {
                    filtered.add(entry);
                } else if (((HistoryContext.selectedHistoryMode === 1) && (entry.gameMode === "Two Players"))) {
                    filtered.add(entry);
                }
            }
            return filtered;
        }
